function renderProjectProgress(s){const derivedStages=s.stages.map(stage=>{const items=s.subtasks.filter(item=>item.stageId===stage.id);return {...stage,status:getProjectStageStatus(stage,items),progress:getProjectStageProgress(stage,items),completed:items.filter(item=>item.status==='completed').length,total:items.length};}),upcoming=[...derivedStages.map(x=>({...x,kind:'Etapa'})),...s.subtasks.map(x=>({...x,kind:'Subtarea'}))].filter(x=>x.dueDate&&x.status!=='completed').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,6);return `<div class="gp-progress-view ${s.progress===100?'is-complete':''}"><div class="gp-progress-overview"><div class="gp-ring big" style="--progress:${s.progress}%"><strong>${s.progress}%</strong><span>general</span></div>${s.progress===100?'<p>✓ Todas las etapas están completadas.</p>':'<p>Completa las subtareas para avanzar el proyecto.</p>'}</div><div class="gp-progress-metrics"><article><span class="gp-progress-stat-icon">▦</span><div><strong>${s.completedStages}/${s.stages.length}</strong><span>Etapas completadas</span></div></article><article><span class="gp-progress-stat-icon">✓</span><div><strong>${s.completedSubtasks}/${s.subtasks.length}</strong><span>Subtareas completadas</span></div></article><article><span class="gp-progress-stat-icon">○</span><div><strong>${s.pendingSubtasks}</strong><span>Pendientes</span></div></article><article><span class="gp-progress-stat-icon">!</span><div><strong>${s.overdue}</strong><span>Vencidas</span></div></article></div><section class="gp-stage-breakdown"><h3>Progreso por etapa</h3>${derivedStages.length?`<div>${derivedStages.map((stage,index)=>`<article><header><span>Etapa ${index+1}</span><strong>${escapeHTML(stage.title)}</strong><b>${stage.progress}%</b></header><div class="gp-stage-progress"><span style="width:${stage.progress}%"></span></div><small>${stage.completed}/${stage.total} subtareas completadas · ${gpLabel(stage.status)}</small></article>`).join('')}</div>`:'<p>Aún no hay etapas para medir.</p>'}</section><section><h3>Próximos vencimientos</h3>${upcoming.length?`<ul>${upcoming.map(x=>`<li><span>${x.kind}</span><strong>${escapeHTML(x.title)}</strong><time>${gpDate(x.dueDate)}${x.dueDate<getGuayaquilDateKey()?' · Atrasado':''}</time></li>`).join('')}</ul>`:'<p>No hay vencimientos próximos.</p>'}</section></div>`;}

