function removeGpRecordFromWorkspace(type,id){if(!workspaceState)return;if(type==='goal')workspaceState={...workspaceState,goals:(workspaceState.goals||[]).filter(item=>item.id!==id)};if(type==='project'){const stageIds=new Set((workspaceState.projectStages||[]).filter(item=>item.projectId===id).map(item=>item.id));workspaceState={...workspaceState,projects:(workspaceState.projects||[]).filter(item=>item.id!==id),goals:(workspaceState.goals||[]).map(item=>item.projectId===id?{...item,projectId:''}:item),projectStages:(workspaceState.projectStages||[]).filter(item=>item.projectId!==id),projectSubtasks:(workspaceState.projectSubtasks||[]).filter(item=>item.projectId!==id&&!stageIds.has(item.stageId))};}if(type==='stage')workspaceState={...workspaceState,projectStages:(workspaceState.projectStages||[]).filter(item=>item.id!==id),projectSubtasks:(workspaceState.projectSubtasks||[]).filter(item=>item.stageId!==id)};if(type==='subtask')workspaceState={...workspaceState,projectSubtasks:(workspaceState.projectSubtasks||[]).filter(item=>item.id!==id)};}
async function gpSave(table,id,payload,message){if(goalsProjectsSaving)return null;goalsProjectsSaving=true;try{const q=id?getSupabaseClient().from(table).update({...payload,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',currentUser.id):getSupabaseClient().from(table).insert({...payload,user_id:currentUser.id});const{data,error}=await q.select().single();if(error)throw error;mergeGpSavedRow(table,data);refreshGpDependentUI();closeGpModal();notify(message,'success');return data;}catch(error){logSupabaseError(`${table} save`,error);notify(error.message||'No se pudo guardar.','error');return null;}finally{goalsProjectsSaving=false;}}
async function saveGoal(e,id){e.preventDefault();const d=gpData(e.currentTarget);await gpSave('goals',id,{title:d.title.trim(),description:d.description.trim()||null,subject_id:d.subject_id||null,project_id:d.project_id||null,target_date:d.target_date||null,priority:d.priority,status:d.status,progress:Number(d.progress||0),show_in_calendar:Boolean(d.show&&d.target_date)},id?'Meta actualizada.':'Meta creada correctamente.');}
async function saveProject(e,id){e.preventDefault();const form=e.currentTarget;if(!validateGpReminderSchedule(form,'project'))return;const d=gpData(form);if(d.start_date&&d.due_date&&d.start_date>d.due_date){notify('La fecha límite no puede ser anterior al inicio.','error');return;}await gpSave('projects',id,{title:d.title.trim(),description:d.description.trim()||null,subject_id:d.subject_id||null,start_date:d.start_date||null,due_date:d.due_date||null,due_time:d.due_time||null,reminders_enabled:Boolean(d.reminders),priority:d.priority,status:d.status,show_in_calendar:Boolean(d.show&&d.due_date)},id?'Proyecto actualizado.':'Proyecto creado correctamente.');}
async function persistDerivedStageStatus(stageId){const ws=loadWorkspace(),stage=ws.projectStages.find(item=>item.id===stageId),items=ws.projectSubtasks.filter(item=>item.stageId===stageId);if(!stage||!items.length)return true;const status=getProjectStageStatus(stage,items);if(stage.status===status)return true;const{data,error}=await getSupabaseClient().from('project_stages').update({status,updated_at:new Date().toISOString()}).eq('id',stageId).eq('user_id',currentUser.id).select().single();if(error){logSupabaseError('project stage derived status',error);return false;}mergeGpSavedRow('project_stages',data);refreshGpDependentUI();return true;}
async function saveStage(e,projectId,id){e.preventDefault();const form=e.currentTarget;if(!validateGpReminderSchedule(form,'stage'))return;const d=gpData(form),ws=loadWorkspace(),stage=ws.projectStages.find(x=>x.id===id),items=id?ws.projectSubtasks.filter(item=>item.stageId===id):[],position=id?stage.position:ws.projectStages.filter(x=>x.projectId===projectId).length,status=items.length?getProjectStageStatus(stage,items):d.status;await gpSave('project_stages',id,{project_id:projectId,title:d.title.trim(),description:d.description.trim()||null,due_date:d.due_date||null,due_time:d.due_time||null,reminders_enabled:Boolean(d.reminders),status,position,show_in_calendar:Boolean(d.show&&d.due_date)},id?'Etapa actualizada.':'Etapa agregada.');}
function getGpLinkedTaskPayload(data,project,includeReminderDefault=false){const payload={user_id:currentUser.id,subject_id:project?.subjectId||null,title:data.title.trim(),description:data.description.trim()||null,due_date:data.due_date||null,due_time:data.due_time||null,priority:normalizeTaskPriority(data.priority),status:normalizeTaskStatus(data.status)};if(includeReminderDefault)payload.reminders_enabled=false;return payload;}
function getGpSubtaskRollbackPayload(item){return{project_id:item.projectId,stage_id:item.stageId,task_id:item.taskId||null,title:item.title,description:item.description||null,due_date:item.dueDate||null,due_time:item.dueTime||null,reminders_enabled:item.remindersEnabled===true,priority:item.priority,status:item.status,position:item.position};}
async function rollbackGpSubtaskLinkChange(sb,item){if(!item?.id)return false;const{data,error}=await sb.from('project_subtasks').update({...getGpSubtaskRollbackPayload(item),updated_at:new Date().toISOString()}).eq('id',item.id).eq('user_id',currentUser.id).select().single();if(error){logSupabaseError('project subtask link rollback',error);return false;}mergeGpSavedRow('project_subtasks',data);refreshGpDependentUI();return true;}
async function removeCreatedGpLinkedTask(sb,taskId){if(!taskId)return true;const{error}=await sb.from('tasks').delete().eq('id',taskId).eq('user_id',currentUser.id);if(error){logSupabaseError('orphan linked task cleanup',error);return false;}return true;}
async function saveSubtask(e,projectId,stageId,id){
    e.preventDefault();
    const form=e.currentTarget;
    if(!validateGpReminderSchedule(form,'subtask')||goalsProjectsSaving)return;

    const data=gpData(form),workspace=loadWorkspace(),old=workspace.projectSubtasks.find(item=>item.id===id),project=workspace.projects.find(item=>item.id===projectId),subjectName=workspace.subjects.find(item=>item.id===project?.subjectId)?.name||project?.subject||'General',wantsTask=Boolean(data.add_task),oldTaskId=old?.taskId||null,position=id?old.position:workspace.projectSubtasks.filter(item=>item.stageId===stageId).length,sb=getSupabaseClient();
    let targetTaskId=wantsTask?oldTaskId:null;
    let createdTask=null;
    goalsProjectsSaving=true;

    try{
        if(wantsTask&&!oldTaskId){
            const{data:task,error}=await sb.from('tasks').insert(getGpLinkedTaskPayload(data,project,true)).select('*').single();
            if(error)throw new Error(`No se pudo crear la tarea vinculada: ${error.message}`);
            createdTask=task;
            targetTaskId=task.id;
        }

        const subtaskPayload={project_id:projectId,stage_id:stageId,task_id:targetTaskId,title:data.title.trim(),description:data.description.trim()||null,due_date:data.due_date||null,due_time:data.due_time||null,reminders_enabled:Boolean(data.reminders),priority:data.priority,status:data.status,position};
        const query=id?sb.from('project_subtasks').update({...subtaskPayload,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',currentUser.id):sb.from('project_subtasks').insert({...subtaskPayload,user_id:currentUser.id});
        const{data:savedSubtask,error:subtaskError}=await query.select('*').single();
        if(subtaskError){
            const cleaned=!createdTask||await removeCreatedGpLinkedTask(sb,createdTask.id);
            throw new Error(cleaned?`No se pudo guardar la subtarea: ${subtaskError.message}`:`No se pudo guardar la subtarea ni eliminar la tarea temporal creada: ${subtaskError.message}`);
        }
        mergeGpSavedRow('project_subtasks',savedSubtask);

        if(wantsTask){
            let savedTask=createdTask;
            if(oldTaskId){
                const taskPayload=getGpLinkedTaskPayload(data,project,false);
                delete taskPayload.user_id;
                const{data:updatedTask,error:taskError}=await sb.from('tasks').update({...taskPayload,updated_at:new Date().toISOString()}).eq('id',oldTaskId).eq('user_id',currentUser.id).select('*').single();
                if(taskError){
                    const rolledBack=await rollbackGpSubtaskLinkChange(sb,old);
                    throw new Error(rolledBack?`No se pudo actualizar la tarea vinculada: ${taskError.message}`:`No se pudo actualizar la tarea vinculada ni restaurar la subtarea: ${taskError.message}`);
                }
                savedTask=updatedTask;
            }
            commitSavedTaskToWorkspace(savedTask,subjectName);
            refreshTaskDependentUI();
        }else if(oldTaskId){
            const{error:deleteError}=await sb.from('tasks').delete().eq('id',oldTaskId).eq('user_id',currentUser.id).select('id').single();
            if(deleteError){
                const rolledBack=await rollbackGpSubtaskLinkChange(sb,old);
                throw new Error(rolledBack?`No se pudo desvincular la tarea: ${deleteError.message}`:`No se pudo eliminar la tarea vinculada ni restaurar la relación: ${deleteError.message}`);
            }
            removeTaskFromWorkspace(oldTaskId);
            refreshTaskDependentUI();
        }

        await persistDerivedStageStatus(stageId);
        refreshGpDependentUI();
        closeGpModal();
        notify(id?'Subtarea actualizada.':'Subtarea creada.','success');
    }catch(error){
        logSupabaseError('project subtask task link save',error);
        notify(error.message||'No se pudo guardar la subtarea.','error');
    }finally{
        goalsProjectsSaving=false;
    }
}
async function toggleGpComplete(type,id){const key=type==='goal'?'goals':'projects',x=loadWorkspace()[key].find(i=>i.id===id);if(!x)return;await gpSave(type==='goal'?'goals':'projects',id,type==='goal'?{status:x.status==='completed'?'in_progress':'completed',progress:x.status==='completed'?Math.min(x.progress,99):100}:{status:x.status==='completed'?'in_progress':'completed'},`${type==='goal'?'Meta':'Proyecto'} actualizado.`);}
async function toggleGpCalendar(type,id){const key=type==='goal'?'goals':'projects',x=loadWorkspace()[key].find(i=>i.id===id),date=type==='goal'?x?.targetDate:x?.dueDate;if(!date){notify('Añade una fecha antes de mostrarlo en Calendario.','error');return;}await gpSave(type==='goal'?'goals':'projects',id,{show_in_calendar:!x.showInCalendar},'Calendario actualizado.');}
function toggleProjectSubtaskDescription(id){expandedProjectSubtasks.has(id)?expandedProjectSubtasks.delete(id):expandedProjectSubtasks.add(id);renderGoalsProjects(loadWorkspace());}
async function toggleProjectSubtask(id){
    if(goalsProjectsSaving||savingProjectSubtasks.has(id))return;
    const ws=loadWorkspace(),x=ws.projectSubtasks.find(item=>item.id===id),stage=ws.projectStages.find(item=>item.id===x?.stageId);
    if(!x||!stage)return;
    const status=x.status==='completed'?'pending':'completed',sb=getSupabaseClient();
    savingProjectSubtasks.add(id);
    patchGpWorkspaceItem('projectSubtasks',id,{status});
    const optimisticWorkspace=loadWorkspace(),optimisticItems=optimisticWorkspace.projectSubtasks.filter(item=>item.stageId===stage.id),stageStatus=getProjectStageStatus(stage,optimisticItems);
    patchGpWorkspaceItem('projectStages',stage.id,{status:stageStatus});
    refreshGpDependentUI();

    try{
        const{data:subtaskData,error:subtaskError}=await sb.from('project_subtasks').update({status,updated_at:new Date().toISOString()}).eq('id',id).eq('user_id',currentUser.id).select().single();
        if(subtaskError)throw subtaskError;
        mergeGpSavedRow('project_subtasks',subtaskData);

        let secondaryError=false;
        if(stage.status!==stageStatus){
            const{data:savedStage,error:stageError}=await sb.from('project_stages').update({status:stageStatus,updated_at:new Date().toISOString()}).eq('id',stage.id).eq('user_id',currentUser.id).select().single();
            if(stageError){logSupabaseError('project stage derived status',stageError);secondaryError=true;}else mergeGpSavedRow('project_stages',savedStage);
        }

        if(x.taskId){
            const taskStatus=normalizeTaskStatus(status);
            const{data:savedTask,error:taskError}=await sb.from('tasks').update({status:taskStatus,updated_at:new Date().toISOString()}).eq('id',x.taskId).eq('user_id',currentUser.id).select().single();
            if(taskError){logSupabaseError('linked task status',taskError);secondaryError=true;}else{commitTaskStatusToWorkspace(savedTask.id,normalizeTaskStatus(savedTask.status));refreshTaskDependentUI();}
        }

        if(secondaryError)notify('Subtarea actualizada, pero una dependencia no pudo sincronizarse.','info');
        else notify(status==='completed'?'Subtarea completada.':'Subtarea marcada como pendiente.','success');
    }catch(error){
        logSupabaseError('project subtask toggle',error);
        patchGpWorkspaceItem('projectSubtasks',id,{status:x.status});
        const rollbackWorkspace=loadWorkspace(),rollbackItems=rollbackWorkspace.projectSubtasks.filter(item=>item.stageId===stage.id),rollbackStageStatus=getProjectStageStatus(stage,rollbackItems);
        patchGpWorkspaceItem('projectStages',stage.id,{status:rollbackStageStatus});
        refreshGpDependentUI();
        notify('No se pudo actualizar la subtarea.','error');
    }finally{
        finishProjectSubtaskSaving(id);
    }
}
function requestProjectStageCompletion(id){const ws=loadWorkspace(),stage=ws.projectStages.find(item=>item.id===id),items=ws.projectSubtasks.filter(item=>item.stageId===id);if(!stage)return;const completed=getProjectStageStatus(stage,items)==='completed';if(!items.length){toggleProjectStageCompletion(id);return;}const title=completed?'¿Marcar esta etapa como pendiente?':'¿Completar esta etapa?',text=completed?'Las subtareas permanecerán como están. El estado final se recalculará según sus subtareas.':'También se marcarán como completadas todas sus subtareas.',label=completed?'Sí, continuar':'Sí, completar';openGpModal(title,`<p class="gp-confirm-copy">${text}</p>`,e=>{e.preventDefault();applyProjectStageCompletion(id,!completed);},false,'gp-stage-confirm',label);}
async function applyProjectStageCompletion(id,complete){if(goalsProjectsSaving)return;const ws=loadWorkspace(),stage=ws.projectStages.find(item=>item.id===id),items=ws.projectSubtasks.filter(item=>item.stageId===id);if(!stage)return;const sb=getSupabaseClient(),now=new Date().toISOString();goalsProjectsSaving=true;try{if(complete&&items.length){const{error:subtaskError}=await sb.from('project_subtasks').update({status:'completed',updated_at:now}).eq('stage_id',id).eq('user_id',currentUser.id);if(subtaskError)throw subtaskError;}const requestedStatus=complete?'completed':'pending',{error:stageError}=await sb.from('project_stages').update({status:requestedStatus,updated_at:now}).eq('id',id).eq('user_id',currentUser.id);if(stageError)throw stageError;await syncWorkspaceFromSupabase();refreshWorkspaceUI();closeGpModal();if(!complete&&items.length){await persistDerivedStageStatus(id);notify('Las subtareas permanecen como están; la etapa se recalculó automáticamente.','success');}else notify(complete?'Etapa completada.':'Etapa marcada como pendiente.','success');}catch(error){logSupabaseError('project stage completion',error);await syncWorkspaceFromSupabase();refreshWorkspaceUI();notify(error.message||'No se pudo actualizar la etapa.','error');}finally{goalsProjectsSaving=false;}}
async function toggleProjectStageCompletion(id){if(goalsProjectsSaving)return;const ws=loadWorkspace(),stage=ws.projectStages.find(item=>item.id===id),items=ws.projectSubtasks.filter(item=>item.stageId===id);if(!stage||items.length)return;await applyProjectStageCompletion(id,stage.status!=='completed');}
async function moveProjectStage(id,delta){const ws=loadWorkspace(),x=ws.projectStages.find(i=>i.id===id),list=ws.projectStages.filter(i=>i.projectId===x?.projectId).sort((a,b)=>a.position-b.position),index=list.findIndex(i=>i.id===id),other=list[index+delta];if(!x||!other)return;const sb=getSupabaseClient(),[a,b]=await Promise.all([sb.from('project_stages').update({position:other.position}).eq('id',x.id).eq('user_id',currentUser.id),sb.from('project_stages').update({position:x.position}).eq('id',other.id).eq('user_id',currentUser.id)]);if(a.error||b.error){notify('No se pudo cambiar el orden.','error');return;}await syncWorkspaceFromSupabase();refreshWorkspaceUI();notify('Orden actualizado.','success');}
function openGpDelete(type,id){openGpModal(`¿Eliminar este ${{goal:'meta',project:'proyecto',stage:'etapa',subtask:'subtarea'}[type]}?`,`<p>Esta acción no se puede deshacer.${type==='project'?' Se eliminarán etapas y subtareas; las metas y tareas reales se conservarán.':''}</p>`,e=>{e.preventDefault();deleteGpRecord(type,id);},true,type==='subtask'?'gp-subtask-delete-confirm':'');}
async function deleteGpRecord(type,id){if(goalsProjectsSaving)return;const workspace=loadWorkspace(),stageId=type==='subtask'?workspace.projectSubtasks.find(item=>item.id===id)?.stageId:'',table={goal:'goals',project:'projects',stage:'project_stages',subtask:'project_subtasks'}[type],form=document.querySelector('#gp-modal form'),button=form?.querySelector('button[type="submit"]'),label=button?.textContent||'Eliminar';goalsProjectsSaving=true;if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Eliminando...';}try{const{error}=await getSupabaseClient().from(table).delete().eq('id',id).eq('user_id',currentUser.id);if(error)throw error;if(type==='project')activeProjectId='';removeGpRecordFromWorkspace(type,id);refreshGpDependentUI();if(stageId)await persistDerivedStageStatus(stageId);closeGpModal();notify('Elemento eliminado.','success');}catch(error){notify(error.message||'No se pudo eliminar.','error');if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.textContent=label;}}finally{goalsProjectsSaving=false;}}
function toggleProjectMapStage(id){const workspace=loadWorkspace(),hasSubtasks=workspace.projectSubtasks.some(item=>item.stageId===id);if(!hasSubtasks)return;collapsedProjectStages.has(id)?collapsedProjectStages.delete(id):collapsedProjectStages.add(id);renderGoalsProjects(workspace);}
function setProjectMapCollapsed(value){const workspace=loadWorkspace();workspace.projectStages.filter(stage=>stage.projectId===activeProjectId&&workspace.projectSubtasks.some(item=>item.stageId===stage.id)).forEach(stage=>value?collapsedProjectStages.add(stage.id):collapsedProjectStages.delete(stage.id));renderGoalsProjects(workspace);}

document.addEventListener('click',event=>{const trigger=event.target.closest('.gp-select-trigger'),option=event.target.closest('.gp-select-menu [role="option"]');if(trigger){toggleGpSelect(trigger);return;}if(option){selectGpOption(option);return;}if(!event.target.closest('[data-gp-select]'))closeGpSelects();});
document.addEventListener('keydown',event=>{const trigger=event.target.closest('.gp-select-trigger'),option=event.target.closest('.gp-select-menu [role="option"]');if(trigger&&event.key==='Escape'){event.preventDefault();closeGpSelects();trigger.focus();return;}if(trigger&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();toggleGpSelect(trigger,true);const options=[...trigger.closest('[data-gp-select]').querySelectorAll('[role="option"]')];(event.key==='ArrowUp'?options.at(-1):options[0])?.focus();return;}if(!option)return;const options=[...option.parentElement.querySelectorAll('[role="option"]')],index=options.indexOf(option);if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?options.length-1:event.key==='ArrowDown'?(index+1)%options.length:(index-1+options.length)%options.length;options[next]?.focus();}else if(event.key==='Enter'||event.key===' '){event.preventDefault();selectGpOption(option);}else if(event.key==='Escape'){event.preventDefault();const triggerButton=option.closest('[data-gp-select]').querySelector('.gp-select-trigger');closeGpSelects();triggerButton?.focus();}});
